package executionbridge

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"strings"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = Describe("Strict host text codec", func() {
	const a = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
	const p = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
	const q = "cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"
	// Independent literal fixture, never generated by the encoder under test.
	const wire = `{"codec":"host-execution-text","version":"1","admission":"` + a + `","provenance":"` + p + `","projection":"` + q + `","text":"hello"}`
	decode := func(b []byte) (textProjection, error) { return decodeTextEnvelope(b, a, p, q) }
	reject := func(s string) {
		out, err := decode([]byte(s))
		Expect(err).To(MatchError("execution bridge codec: invalid or unavailable"))
		Expect(out.Text()).To(BeEmpty())
		Expect(out.Envelope()).To(BeNil())
	}
	It("encodes exact independently specified wire bytes", func() {
		out, err := encodeAuthorizedText("hello", a, p, q)
		Expect(err).NotTo(HaveOccurred())
		Expect(string(out.Envelope())).To(Equal(wire))
	})
	It("decodes independently specified wire and discloses digests explicitly", func() {
		out, err := decode([]byte(wire))
		Expect(err).NotTo(HaveOccurred())
		Expect(out.Text()).To(Equal("hello"))
		x, y, z := out.Digests()
		Expect([]string{x, y, z}).To(Equal([]string{a, p, q}))
	})
	It("matches an independently pinned wire SHA256", func() {
		out, err := encodeAuthorizedText("hello", a, p, q)
		Expect(err).NotTo(HaveOccurred())
		h := sha256.Sum256(out.Envelope())
		Expect(hex.EncodeToString(h[:])).To(Equal("a531919b7a9cf118180f633e64a97271411791ca9c8c9132c76effe879b67b55"))
	})
	It("preserves all legitimate escapes and Unicode without normalization", func() {
		for _, text := range []string{"\x00\b\f\n\r\t\"\\/<>&", "é e\u0301 😀 \ufffd \u2028\u2029", "", "\\ud800"} {
			out, err := encodeAuthorizedText(text, a, p, q)
			Expect(err).NotTo(HaveOccurred())
			got, err := decode(out.Envelope())
			Expect(err).NotTo(HaveOccurred())
			Expect(got.Text()).To(Equal(text))
		}
	})
	It("accepts valid surrogate pairs and escaped field names", func() {
		s := strings.Replace(wire, `"text":"hello"`, `"te\u0078t":"\ud83d\ude00"`, 1)
		out, err := decode([]byte(s))
		Expect(err).NotTo(HaveOccurred())
		Expect(out.Text()).To(Equal("😀"))
	})
	It("retains the original replay bytes including whitespace and escape spelling", func() {
		s := " \n" + strings.Replace(wire, `hello`, `h\u0065llo`, 1) + "\t\r\n"
		out, err := decode([]byte(s))
		Expect(err).NotTo(HaveOccurred())
		Expect(string(out.Envelope())).To(Equal(s))
	})
	It("treats fresh envelope-looking text as text exactly once", func() {
		out, err := encodeAuthorizedText(wire, a, p, q)
		Expect(err).NotTo(HaveOccurred())
		got, err := decode(out.Envelope())
		Expect(err).NotTo(HaveOccurred())
		Expect(got.Text()).To(Equal(wire))
	})
	It("owns input and each disclosed envelope buffer", func() {
		b := []byte(wire)
		out, err := decode(b)
		Expect(err).NotTo(HaveOccurred())
		b[0] = '!'
		x := out.Envelope()
		x[0] = '!'
		Expect(string(out.Envelope())).To(Equal(wire))
		Expect(out.Text()).To(Equal("hello"))
	})
	It("redacts direct nested pointer and invalid-verb diagnostics and JSON", func() {
		out, err := decode([]byte(wire))
		Expect(err).NotTo(HaveOccurred())
		for _, v := range []any{out, &out, []textProjection{out}, struct{ X textProjection }{out}, map[string]textProjection{"x": out}} {
			for _, format := range []string{"%v", "%+v", "%#v", "%s", "%q", "%d"} {
				s := fmt.Sprintf(format, v)
				Expect(s).NotTo(ContainSubstring("hello"))
				Expect(s).NotTo(ContainSubstring(a))
			}
			b, e := json.Marshal(v)
			Expect(e).NotTo(HaveOccurred())
			Expect(string(b)).NotTo(ContainSubstring("hello"))
			Expect(string(b)).NotTo(ContainSubstring(a))
		}
	})
	It("keeps zero projections inert", func() {
		var out textProjection
		Expect(out.Text()).To(BeEmpty())
		Expect(out.Envelope()).To(BeNil())
		x, y, z := out.Digests()
		Expect(x + y + z).To(BeEmpty())
	})
	It("accepts exactly one MiB fresh and projected UTF8 bytes", func() {
		text := strings.Repeat("x", 1048576)
		Expect(validateFreshText(text)).To(Succeed())
		out, err := encodeAuthorizedText(text, a, p, q)
		Expect(err).NotTo(HaveOccurred())
		got, err := decode(out.Envelope())
		Expect(err).NotTo(HaveOccurred())
		Expect(got.Text()).To(Equal(text))
	})
	It("rejects one byte overflow in fresh projected and decoded text", func() {
		text := strings.Repeat("x", 1048577)
		Expect(validateFreshText(text)).To(HaveOccurred())
		out, err := encodeAuthorizedText(text, a, p, q)
		Expect(err).To(HaveOccurred())
		Expect(out.Envelope()).To(BeNil())
		reject(strings.Replace(wire, "hello", text, 1))
	})
	It("measures UTF8 limits in bytes rather than rune counts", func() {
		text := strings.Repeat("é", 524288)
		Expect(validateFreshText(text)).To(Succeed())
		Expect(validateFreshText(text + "x")).To(HaveOccurred())
	})
	It("admits worst-case six MiB escaping plus fixed overhead", func() {
		out, err := encodeAuthorizedText(strings.Repeat("\x00", 1048576), a, p, q)
		Expect(err).NotTo(HaveOccurred())
		Expect(len(out.Envelope())).To(Equal(6291456 + len(wire) - 5))
		Expect(len(out.Envelope())).To(BeNumerically("<=", 6292480))
		_, err = decode(out.Envelope())
		Expect(err).NotTo(HaveOccurred())
	})
	It("accepts envelope byte boundary and rejects one byte overflow before parsing", func() {
		b := append([]byte(wire), bytes.Repeat([]byte(" "), 6292480-len(wire))...)
		_, err := decode(b)
		Expect(err).NotTo(HaveOccurred())
		b = append(b, ' ')
		_, err = decode(b)
		Expect(err).To(HaveOccurred())
		_, err = decode(bytes.Repeat([]byte("!"), 6292481))
		Expect(err).To(HaveOccurred())
	})
	It("rejects invalid fresh and projected UTF8", func() {
		text := string([]byte{255})
		Expect(validateFreshText(text)).To(HaveOccurred())
		_, err := encodeAuthorizedText(text, a, p, q)
		Expect(err).To(HaveOccurred())
	})
	It("rejects invalid raw JSON UTF8 rather than replacing it", func() { reject(strings.Replace(wire, "hello", string([]byte{255}), 1)) })
	It("rejects unpaired high low and reversed Unicode surrogates", func() {
		for _, s := range []string{`\ud800`, `\udfff`, `\ud800x`, `\ud800\u0041`, `\udfff\ud800`, `\ud800\ud800`, `\ud800\\udc00`} {
			reject(strings.Replace(wire, "hello", s, 1))
		}
	})
	It("rejects invalid Unicode in keys even unknown fields", func() { reject(strings.Replace(wire, `"text"`, `"\ud800"`, 1)) })
	It("rejects duplicate keys including escaped-equivalent names", func() {
		for _, key := range []string{`text`, `te\u0078t`, `codec`, `admission`, `version`, `provenance`, `projection`} {
			reject(strings.TrimSuffix(wire, "}") + `,"` + key + `":"hello"}`)
		}
	})
	It("rejects unknown keys and case-insensitive aliases", func() {
		for _, key := range []string{"Text", "TEXT", "extra", "binding"} {
			reject(strings.Replace(wire, `"text"`, `"`+key+`"`, 1))
		}
	})
	It("requires every exact schema field", func() {
		for _, field := range []string{`"codec":"host-execution-text",`, `"version":"1",`, `"admission":"` + a + `",`, `"provenance":"` + p + `",`, `"projection":"` + q + `",`, `,"text":"hello"`} {
			reject(strings.Replace(wire, field, "", 1))
		}
	})
	It("rejects null scalars arrays objects and numeric version confusion", func() {
		for _, value := range []string{"null", "true", "1", "[]", "{}", `{"nested":[{"text":"secret"}]}`} {
			for _, old := range []string{`"hello"`, `"1"`, `"` + a + `"`} {
				reject(strings.Replace(wire, old, value, 1))
			}
		}
		for _, s := range []string{"null", "[]", "true", "1", `"hello"`} {
			reject(s)
		}
	})
	It("rejects unknown codec and version strings", func() {
		reject(strings.Replace(wire, "host-execution-text", "other", 1))
		reject(strings.Replace(wire, `"1"`, `"2"`, 1))
	})
	It("requires lowercase hex digest domains in inputs and wire", func() {
		for _, bad := range []string{"", strings.Repeat("A", 64), strings.Repeat("g", 64), strings.Repeat("a", 63), strings.Repeat("a", 65)} {
			for i := 0; i < 3; i++ {
				args := []string{a, p, q}
				args[i] = bad
				_, err := encodeAuthorizedText("hello", args[0], args[1], args[2])
				Expect(err).To(HaveOccurred())
				_, err = decodeTextEnvelope([]byte(wire), args[0], args[1], args[2])
				Expect(err).To(HaveOccurred())
			}
			reject(strings.Replace(wire, a, bad, 1))
		}
	})
	It("rejects each mismatched expected admission provenance or policy", func() {
		for i := 0; i < 3; i++ {
			args := []string{a, p, q}
			args[i] = strings.Repeat("d", 64)
			out, err := decodeTextEnvelope([]byte(wire), args[0], args[1], args[2])
			Expect(err).To(HaveOccurred())
			Expect(out.Envelope()).To(BeNil())
		}
	})
	It("rejects trailing input and multiple objects but permits JSON whitespace", func() {
		for _, tail := range []string{wire, "null", "x", "\x00", "\v"} {
			reject(wire + tail)
		}
		_, err := decode([]byte(wire + " \t\r\n"))
		Expect(err).NotTo(HaveOccurred())
	})
	It("rejects malformed JSON and never echoes secret parser input", func() {
		for _, s := range []string{"", "{", strings.TrimSuffix(wire, "}"), strings.Replace(wire, "hello", "secret\nraw", 1), strings.Replace(wire, "hello", `\x41`, 1), strings.Replace(wire, "hello", `\uZZZZ`, 1)} {
			reject(s)
		}
	})
	It("runs a finite fuzz seed and deterministic mutation table without panics", func() {
		seeds := [][]byte{nil, []byte(wire), []byte(`{"text":"\ud800"}`), []byte("\xff"), []byte("{}{}"), []byte("[]")}
		for _, seed := range seeds {
			_, _ = decode(seed)
		}
		for i := 0; i < len(wire); i++ {
			b := []byte(wire)
			b[i] = 0xff
			_, err := decode(b)
			Expect(err).To(HaveOccurred())
		}
	})
})
